package com.flutterguard.app.scan.parsers

/**
 * Release Flutter APKs ship `assets/flutter_assets/pubspec.yaml` verbatim — the
 * project's own dependency manifest, with exact version constraints. That is a
 * stronger signal than the package names recoverable from `NOTICES.Z`: it names
 * the SDKs the developer actually chose (AI providers, payment, analytics) and
 * the versions that carry known CVEs.
 *
 * Parsed by hand rather than with a YAML library: the file is generated by the
 * Flutter tool, flat, and only the `dependencies:` block matters. A real parser
 * would be a dependency and a larger attack surface for no extra signal.
 */
object Pubspec {

    data class Info(
        val name: String? = null,
        val version: String? = null,
        val deps: Map<String, String> = emptyMap(),
    ) {
        val isEmpty: Boolean get() = name == null && deps.isEmpty()
    }

    private val topLevel = Regex("""^([A-Za-z_][\w]*):[ \t]*(.*)$""")
    private val pubName = Regex("""^[a-z][a-z0-9_]{1,60}$""")

    fun parse(text: String, maxDeps: Int = 400): Info {
        var name: String? = null
        var version: String? = null
        val deps = LinkedHashMap<String, String>()
        var inDeps = false

        for (raw in text.lineSequence()) {
            if (raw.isBlank() || raw.trimStart().startsWith("#")) continue
            val indented = raw[0] == ' ' || raw[0] == '\t'
            if (!indented) {
                val m = topLevel.find(raw) ?: continue
                val key = m.groupValues[1]
                val value = unquote(m.groupValues[2]).take(120)
                inDeps = key == "dependencies"
                when (key) {
                    "name" -> if (pubName.matches(value)) name = value
                    "version" -> if (value.isNotEmpty()) version = value
                }
                continue
            }
            if (!inDeps) continue
            // Two-space indented `pkg: constraint`. Nested structures (git:, sdk:)
            // are skipped: they carry no version constraint worth reporting.
            val depth = raw.takeWhile { it == ' ' }.length
            if (depth != 2) continue
            val line = raw.trim()
            val colon = line.indexOf(':')
            if (colon <= 0) continue
            val dep = line.substring(0, colon).trim()
            if (!pubName.matches(dep)) continue
            // Empty value means a nested block (`path:`, `git:`, `sdk: flutter`):
            // no version constraint to report, so it is not a usable dependency.
            val constraint = unquote(line.substring(colon + 1)).take(40)
            if (constraint.isEmpty()) continue
            deps[dep] = constraint
            if (deps.size >= maxDeps) break
        }
        return Info(name, version, deps)
    }

    private fun unquote(s: String): String {
        val t = s.trim()
        return when {
            t.length >= 2 && (t.first() == '"' || t.first() == '\'') && t.last() == t.first() -> t.substring(1, t.length - 1)
            else -> t.substringBefore(" #").trim()
        }
    }
}
